"""Neighbour content for slava, ada, olga, zoya: people/<id>.tsv (lines, requests, notes).

Arcs (three years each):
- slava: the garage mechanic who secretly paints the player's beds -> tyre planters and seed bombs on the
  waste lot -> his first canvas -> an exhibition called «Зелёная улица» and a portrait of the player.
- ada: the retired actress -> memoirs and a bulb bed by the museum steps -> «Двенадцать месяцев» staged
  in the courtyard -> «Сад ролей», her printed book, the last bow that is only an interval.
- olga: the tired vet with three-legged Tripod -> kittens to rehome, a first day off -> the clinic's
  garden for animals, Prickles the hedgehog, a holiday -> the healing yard, an intern, learning to rest.
- zoya: the tailor -> linen, woad blue, madder red, onion and chamomile yellow, a colour book -> aprons
  for the district, cloaks for the play -> a quilt of everyone's patches hung over the courtyard arch.
"""
from common import write

COLS = "t n gap months when hearts needs reward text_ru text_en reply_ru reply_en sets".split()


def L(when, ru, en):
    return ("line", "", "", "", when, "", "", "", ru, en, "", "", "")


def R(gap, months, when, hearts, needs, reward, ru, en, rru, ren, sets=""):
    return ("req", None, gap, months, when, hearts, needs, reward, ru, en, rru, ren, sets)


def N(gap, months, when, hearts, needs, reward, ru, en):
    return ("note", None, gap, months, when, hearts, needs, reward, ru, en, "", "", "")


def number(rows):
    out, n = [], {"req": 0, "note": 0}
    for r in rows:
        r = list(r)
        if r[0] in n:
            n[r[0]] += 1
            r[1] = n[r[0]]
        out.append(r)
    return out


